use crate::model::{Error, Result};

pub const COMMANDS: &[&str] = &[
    "tui",
    "search",
    "play",
    "pause",
    "resume",
    "toggle",
    "stop",
    "next",
    "prev",
    "seek",
    "volume",
    "mode",
    "status",
    "favorites",
    "history",
    "daily",
    "queue",
    "playlist",
    "like",
    "lyrics",
    "lyrics-bar",
    "widgets",
    "boss",
    "tray",
    "download",
    "retry",
    "source",
    "config",
    "update",
    "doctor",
    "mcp",
    "daemon",
    "help",
];
pub const KEYS:&str="终端快捷键（wocli tui）\n\n/ 搜索；Enter 播放；Space 暂停/继续\nj/k 或 ↑/↓ 选择；g/G 顶部/底部；Ctrl+U/D 翻页\n[ / ] 上一首/下一首；←/→ 跳转 5 秒；+/- 音量\n键盘多媒体按键（播放/暂停、上一首、下一首、音量调节）原生可用\nf 喜欢；c 收藏到歌单；a 加入队列；x 歌曲操作\nd 下载所选歌曲；D 下载任务；m 播放方式\nv 展开歌词；V 开关频谱动效；l 刷新歌词；Ctrl+R 重试当前歌曲\nShift+B / Ctrl+B / F12 老板键（固定虚构身份的工程代码伪装，即刻静音暂停，B/Ctrl+B/Esc 恢复）\n每日推荐中 r 在线刷新，x 打开歌曲操作并排除
I 导入歌单；E 导出当前歌单（b 音乐库菜单也可进入）\nTab 切换侧栏；b 音乐库；? 帮助；Esc 返回；q 退出界面\n退出界面后后台继续播放；wocli stop 停止播放，wocli daemon stop 退出后台。\n\n音源管理：wocli help source";

pub fn text(topic: Option<&str>) -> Result<String> {
    let topic = topic.unwrap_or("");
    let body=match topic{
        ""|"help"|"thelp"=>return Ok(format!("{}\n分项帮助：wocli help <命令>（也支持 thelp、<命令> --help）\n例如：wocli help download、wocli help source、wocli help keys\n",crate::cli::HELP)),
        "keys"|"tui"=>return Ok(KEYS.into()),
        "source"|"sources"=>"用法：\n  wocli source list                    按尝试顺序列出音源\n  wocli source show ID                 查看单个音源\n  wocli source add 文件或网址 [--name 名称]\n  wocli source enable ID               启用\n  wocli source disable ID              停用\n  wocli source prefer ID               启用并优先使用\n  wocli source remove ID               移除用户音源\n  wocli source test ID [--id 歌曲ID --quality 128k]\n\n默认先尝试酷我内置，再尝试酷我移动接口，均直连国内平台。\n播放、下载共用换源顺序，全部失败才跳过歌曲或报告下载错误。\n支持本地/HTTP(S) 的 LX .js 及 HTTP 模板 .json，改动在下次请求生效。\n示例：wocli source add ./音源.js\n      wocli source prefer user-xxxxxxxxxxxx\n当前适配酷我 kw/musicUrl，不混用 QQ、网易等平台 ID。\nLX 支持事件、Promise、HTTP、定时器、Buffer 工具、MD5、zlib；暂不支持 AES/RSA/Node.js API。\n详见 docs/sources.md。",
        "download"=>"用法：wocli download --id ID [--quality best --lyrics --output 目录 --force --direct]\n      wocli download 关键词 --pick N [选项]\n示例：wocli download --id 228908 --quality 128k --lyrics --output ~/Music\n--lyrics 同时保存 .lrc；--force 覆盖已有文件；--direct 忽略代理。\n终端界面选中歌曲按 d，或在下载任务中点击“新建 d”。\n下载失败会尝试其他启用音源。已有同名文件需要 --force；本地音频无需再下载。",
        "search"=>"用法：wocli search 关键词 [--page 1 --limit 20 --json --direct]\n示例：wocli search 周杰伦 --page 2 --limit 10\n页码从 1 开始，每页 1–100 首。目前搜索使用酷我目录。",
        "play"=>"用法：wocli play 关键词 [--pick N --quality best]\n      wocli play --id ID [--quality best --no-wait --direct]\n      wocli play /path/song.flac\n      wocli play                       继续当前歌曲/队列\n示例：wocli play 晴天 --pick 1\n质量：best / flac / 320k / 128k；会依序降级并尝试其他音源。\n脚本调用请用 --pick 或 --id 明确选择；--no-wait 不等待加载。",
        "retry"=>"用法：wocli retry [--quality best --no-wait]\n重新解析并播放当前歌曲，重新尝试所有启用音源。\n终端快捷键：Ctrl+R。",
        "daily"=>"用法：wocli daily [--offline --refresh --json]\n      wocli daily play [--no-wait]\n      wocli daily add\n      wocli daily dislike --id ID\n      wocli daily undo --id ID\n每天按本地日期保存一份推荐；--refresh 重新生成，--offline 仅使用本地候选。\n推荐基于收藏、歌单与历史；在线生成时搜索偏爱歌手。历史表示成功加载，不代表听完。\nTUI 的每日推荐使用已生成的快照；无快照时生成本地推荐。按 r 在线刷新，歌曲操作可排除，按 u 恢复；托盘菜单可播放。\n歌曲可能无法播放；不喜欢只排除日推，不删除收藏或歌单。",
        "queue"=>"用法：wocli queue list\n      wocli queue add --id ID [--next]\n      wocli queue add 关键词 --pick N\n      wocli queue remove N\n      wocli queue clear\nN 从 1 开始；--next 将歌曲加入当前歌曲之后。",
        "playlist"=>"用法：wocli playlist list\n      wocli playlist create 名称\n      wocli playlist show 名称\n      wocli playlist add 名称 --id ID\n      wocli playlist remove 名称 --id ID\n      wocli playlist rename 旧名称 新名称\n      wocli playlist delete 名称\n      wocli playlist play 名称 [--quality best --no-wait]\n      wocli playlist scan 文件 [--json]\n      wocli playlist import 文件 [--name 名称 --list 名称或序号]\n        [--offline --dry-run --text-order artist-title|title-artist]\n        [--on-conflict rename|error|merge|replace]\n      wocli playlist inspect 名称 [--json]\n      wocli playlist resolve 名称 [--offline --dry-run]\n      wocli playlist match 名称 --entry 序号 --id 目标歌曲ID\n      wocli playlist drop 名称 --entry 序号\n      wocli playlist export 名称 --output 文件 [--format json|csv|tsv|txt|m3u8|jspf --force]\n      wocli playlist backups 名称\n      wocli playlist restore 名称 --id 快照编号\n支持 UTF-8 CSV/TSV/TXT、wocli v1 JSON、LX 单歌单 v2（.lxmc/JSON）、MusicFree 备份、M3U/M3U8/PLS、JSPF。\n默认 TXT 为 歌手 - 歌名；同名默认另存。多歌单用 scan 查看后选择，不会自动合并。\n跨平台只导入曲目信息，匹配到酷我/本地版本后才能播放；未匹配会保留，可重试或手动指定。\n合并、替换和手动修改前保留快照。JSON 完整保留匹配信息；CSV/TXT/JSPF 仅交换元数据，M3U8 需要本地文件。\n在线分享链接、旧版 LX/全量备份、Apple XML/XSPF 暂未支持。含空格的名称请加引号。",
        "seek"=>"用法：wocli seek 秒数\n示例：wocli seek 10（快进），wocli seek -10（后退）。\n相对当前进度跳转，缓冲等待最多 10 秒。",
        "volume"=>"用法：wocli volume 0-100\n示例：wocli volume 60；0 为静音。",
        "mode"=>"用法：wocli mode list|repeat|single|shuffle\n依次为：顺序播放、列表循环、单曲循环、随机播放。\n无法播放的歌曲在所有模式下都会自动跳过。",
        "like"=>"用法：wocli like [--id ID]\n喜欢或取消喜欢指定歌曲；不传 ID 则操作当前歌曲。",
        "lyrics"=>"用法：wocli lyrics [--id ID --refresh --output song.lrc --force]\n不传 ID 则读取当前歌曲歌词。--refresh 忽略歌词缓存，--force 覆盖输出文件。",
        "lyrics-bar"=>"用法：wocli lyrics-bar [on|off|toggle|status]\n开启、关闭、切换或查看任务栏/状态栏实时歌词。",
        "widgets"=>"用法：wocli widgets [on|off|status] [--json]\nWindows 11 系统任务栏公告组件预览，需要单独安装 MSIX 并在 Widgets 面板启用 wocli Feed。\non 选择当前 --home 曲库、开启歌词总开关，并停用该曲库的旧自绘歌词条；off 关闭公告且不自动恢复自绘。\n系统负责公告字体、颜色与主题；系统决定是否显示、时长与每日次数，因此不保证常驻或逐句更新。\nstatus 区分组件心跳、请求与系统回调，回调记录不等于当前可见。地区及具体系统可用性以 Windows 为准。\n详见 docs/windows-taskbar-lyrics.md。",
        "boss"=>"用法：wocli boss [on|off|toggle]\n老板模式（老板键）：立即暂停/静音，隐藏歌词与歌曲信息，保留中性的 wocli 托盘入口。\n再次执行恢复界面，仅此前播放或加载中的歌曲会继续。\n在终端界面（TUI）中按 Shift+B、Ctrl+B 或 F12 触发工作伪装模式（带行号的 Rust 工程代码、诊断与编译终端；使用固定虚构身份，不读取真实用户名、主机名或个人路径），按 b、Shift+B、Ctrl+B、F12 或 Esc 恢复。\n全局键需先运行 wocli tray start；macOS：Ctrl+Shift+B；Windows：Ctrl+Shift+B 或 Ctrl+Alt+B。\nwocli tray status 查看注册结果，失败时检查其他应用的按键占用。\nShift+B 仅用于终端焦点下的非输入状态；tmux 可能占用 Ctrl+B，可改用 F12（部分 Mac 键盘需 Fn+F12）。\nLinux 系统可在桌面快捷键设置中将全局按键绑定至命令 `wocli boss`。",
        "tray"=>"用法：wocli tray start|stop|status\nstart 启动托盘；点击播放或老板模式时按需启动音频后台。\nstatus 显示托盘及全局老板键注册结果；Windows 另显示任务栏子窗口挂接、显隐和失败原因（--json 的 lyrics_surface）。\nWindows 歌词嵌入主任务栏横向空白区，空间不足/读取失败时隐藏，不回退为桌面浮窗。升级后 tray stop 再 tray start。",
        "daemon"=>"用法：wocli daemon start [--tray]\n      wocli daemon status\n      wocli daemon stop\nstop 同时关闭托盘和播放后台。",
        "config"=>"用法：wocli config [配置项 [值]]\n配置项：quality、volume、mode、direct、lyric_offset、lyrics_bar、tray。\n示例：wocli config quality 320k；wocli config direct true\nlyric_offset 使用毫秒，范围 -60000 至 60000；布尔值为 true/false。\n音源请使用 wocli source 管理。",
        "update"=>"用法：wocli update [--check --force --direct --json]\n--check 仅检查；--force 重装当前稳定版；默认校验并安装最新稳定版。\n保留曲库和设置；更新前下载并校验完整，重启先前运行的后台/托盘。",
        "doctor"=>"用法：wocli doctor [--json]\n查看版本、平台、数据目录、网络环境及后台运行状态。\n音源故障可进一步运行 wocli source list / test。",
        "mcp"=>"用法：wocli mcp [serve] [--read-only --direct --home 目录]\n      wocli mcp prompt [--read-only --direct --home 目录 --json]\n      wocli mcp config [--read-only --direct --home 目录]\n      wocli mcp tools [--read-only]\n\nserve 通过标准输入/输出提供本地 MCP 服务，供 AI 客户端启动；不监听 HTTP 端口。\n直接在终端运行 serve 会显示启动成功及可复制给 AI 的接入提示词，等待客户端连接；Ctrl+C 退出。\nprompt 单独输出提示词后退出，包含本机配置与连接验证步骤；--json 输出提示词及配置。\n请复制提示词给支持本地 stdio MCP 的 AI 客户端，由客户端启动自己的服务进程。\nconfig 输出包含当前程序绝对路径的 mcpServers JSON 配置。\ntools 查看工具目录及参数 Schema。--read-only 只开放查询工具。\n\n支持搜索、播放控制、队列、收藏/歌单、歌词、后台下载和已有音源管理。\n播放/下载立即返回，请继续查询状态；关闭 MCP 不会关闭音乐后台。\n不会通过 MCP 执行更新、导入脚本或任意命令。详见 docs/mcp.md。",
        "pause"|"resume"|"toggle"|"play-pause"|"stop"|"next"|"skip"|"prev"|"previous"=>"播放控制：pause 暂停；resume 继续；toggle / play-pause 切换；stop 停止。\nnext / skip 下一首；prev / previous 上一首。切歌支持 --no-wait。\n停止或空闲状态下按播放/暂停或切歌可直接唤起播放；无缝兼容系统全局快捷键与媒体按键绑定。",
        "status"|"favorites"|"history"=>"用法：wocli status | favorites | history [--json]\n分别查看当前播放状态、喜欢列表、最近播放历史。",
        _=>return Err(Error::new(format!("没有“{topic}”的帮助，运行 wocli help 查看命令"))),
    };
    Ok(format!("wocli {topic}\n\n{body}\n\n通用选项：--json 结构化输出；--home 目录 指定数据目录；-h/--help 帮助。\n"))
}
